import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _norm_items(raw_items: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []

    if not raw_items:
        return items

    for item in raw_items:
        if isinstance(item, dict):
            name = item.get("name")
            quantity = item.get("quantity")
            total_price = item.get("totalPrice") or item.get("amount") or item.get("total")
            unit_price = item.get("unitPrice")
            items.append(
                {
                    "name": name,
                    "quantity": quantity,
                    "unit_price": unit_price,
                    "total": total_price,
                }
            )
        else:
            name = getattr(item, "name", None)
            quantity = getattr(item, "quantity", None)
            total_price = getattr(item, "total_price", None) or getattr(item, "total", None)
            unit_price = getattr(item, "unit_price", None)
            items.append(
                {
                    "name": name,
                    "quantity": quantity,
                    "unit_price": unit_price,
                    "total": total_price,
                }
            )

    return items


def extract_receipt(path: str) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            body=f,
        )

    result = poller.result()

    merchant: Optional[str] = None
    tax: Optional[Any] = None
    total: Optional[Any] = None
    items: List[Dict[str, Any]] = []

    docs = getattr(result, "documents", None) or []
    if docs:
        doc = docs[0]
        fields = getattr(doc, "fields", {}) or {}

        merchant_field = fields.get("VendorName") or fields.get("MerchantName") or fields.get("Merchant")
        tax_field = fields.get("TotalTax") or fields.get("Tax") or fields.get("AmountTax")
        total_field = fields.get("InvoiceTotal") or fields.get("Total") or fields.get("AmountDue")
        items_field = fields.get("Items") or fields.get("LineItems")

        if merchant_field is not None:
            merchant = getattr(merchant_field, "content", None) or getattr(merchant_field, "value", None)
        if tax_field is not None:
            tax = getattr(tax_field, "value", None)
            if tax is None:
                tax = getattr(tax_field, "content", None)
        if total_field is not None:
            total = getattr(total_field, "value", None)
            if total is None:
                total = getattr(total_field, "content", None)

        raw_items = None
        if items_field is not None:
            raw_items = getattr(items_field, "value_array", None) or getattr(items_field, "value", None)
            if raw_items is None:
                raw_items = getattr(items_field, "content", None)

        items = _norm_items(raw_items)

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
    }
